struct Info {
    bool ok;
    long long low, high, total;
};

Info go(TreeNode* node, long long& best) {
    const long long INF = 1000000000000000000LL;
    if (node == nullptr) return {true, INF, -INF, 0};
    Info l = go(node->left, best);
